require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';oecrm_require_admin_login();oecrm_require_permission($conn,'notices','view');$id=oecrm_int_param($_GET,'id');$companyId=oecrm_current_company_id($conn);$s=mysqli_prepare($conn,'SELECT * FROM notices WHERE id=? AND company_id=?');mysqli_stmt_bind_param($s,'ii',$id,$companyId);mysqli_stmt_execute($s);$n=mysqli_fetch_assoc(mysqli_stmt_get_result($s));mysqli_stmt_close($s);if(!$n||!$n['attachment_stored_name']){http_response_code(404);exit('Attachment not found.');}$root=realpath(__DIR__.'/../storage/notice_attachments');$path=realpath($root.'/'.$n['attachment_stored_name']);if(!$root||!$path||strpos($path,$root)!==0||!is_file($path)){http_response_code(404);exit('Attachment not found.');}header('Content-Type: '.($n['attachment_mime']?:'application/octet-stream'));header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.str_replace(['"',"\r","\n"],'',$n['attachment_original_name']).'"');readfile($path);exit;
